// Deliberate self-only native public profile edits. This never edits a Nostr
// kind0 identity or installs native account/session authority into device state.
import {boundAccountAccess} from './bound-account-request';
import {publicUuid,record,PublicApiContractError} from './validation';
import type {Resource} from './types';
export const accountProfileFields=['description','discord','twitter','website'] as const;
export type AccountProfileField=typeof accountProfileFields[number];
export type AccountProfilePatch=Partial<Record<AccountProfileField,string>>;
export interface AccountProfileView extends Record<AccountProfileField,string>{accountId:string;userId:string;username:string;roles:string[];version?:number;resource?:Resource;needsRecheck:boolean;}
const encoder=new TextEncoder();
function fail(message:string,status=502):never{throw new PublicApiContractError(message,status);}
function value(input:unknown,field:AccountProfileField,status=502){if(typeof input!=='string'||encoder.encode(input).byteLength>(field==='description'?20000:2048))fail('Invalid '+field+' in native public profile.',status);return input;}
function revision(input:unknown){if(!Number.isSafeInteger(input)||Number(input)<1||Number(input)>2147483647)fail('Invalid shared native user revision.');return Number(input);}
export function createAccountProfileClient(access=boundAccountAccess){return async(input:string,expectedAccountId:string,assertCurrent=()=>{})=>{
 const userId=publicUuid(input),accountId=publicUuid(expectedAccountId);if(userId!==accountId)fail('Only your bound account’s public profile can be edited.',403);
 const account=await access(assertCurrent);account.check();if(account.accountId!==accountId)fail('The selected account changed. Reopen profile settings from your account.',409);
 let state:AccountProfileView={userId,accountId,username:account.username,roles:[],description:'',discord:'',twitter:'',website:'',needsRecheck:true},busy=false;
 const view=()=>Object.freeze({...state,roles:[...state.roles]});
 function observation(input:unknown,write=false){const body=record(input),row=record(body.data),attrs=record(row.attributes),top=record(body.nostr),source=record(row.nostr);if(body.result!=='ok'||body.response!=='entity'||row.type!=='user'||publicUuid(row.id)!==userId)fail('Invalid native account profile target.');for(const provenance of[top,source])if(provenance.scope!=='instance-account'||provenance.source!=='persisted-native-account-profile'||provenance.versionSemantics!=='shared-native-user-revision'||publicUuid(provenance.accountId)!==accountId||publicUuid(provenance.userId)!==userId||(write?provenance.changed!==true:provenance.changed!==undefined))fail('The profile or bound account changed. Reload before editing.',409);if(source.identity!=='native_public_user'||Object.keys(attrs).some(key=>!['username','roles','version',...accountProfileFields].includes(key))||typeof attrs.username!=='string'||!attrs.username||attrs.username.length>256||!Array.isArray(attrs.roles)||attrs.roles.length>128||attrs.roles.some(role=>typeof role!=='string'||!role||encoder.encode(role).byteLength>128))fail('Invalid native public profile presentation.');return{userId,accountId,resource:row as unknown as Resource,username:attrs.username,roles:[...attrs.roles] as string[],version:revision(attrs.version),...Object.fromEntries(accountProfileFields.map(field=>[field,attrs[field]===undefined?'':value(attrs[field],field)])) as Record<AccountProfileField,string>,needsRecheck:false};}
 async function reload(){account.check();if(busy)fail('A profile request is still pending.',409);busy=true;try{const response=await account.request('/nostr/user/'+userId+'/profile?expectedAccountId='+accountId);account.check();if(response.status!==200)fail('Your public account profile could not be loaded ('+response.status+').',response.status);state=observation(response.body);return view();}catch(error){state={...state,needsRecheck:true};throw error;}finally{busy=false;}}
 async function save(input:AccountProfilePatch){account.check();if(busy||state.needsRecheck||state.version===undefined)fail('Reload your public account profile before saving.',409);const object=record(input,'profile changes'),patch:AccountProfilePatch={};if(Object.keys(object).some(key=>!accountProfileFields.includes(key as AccountProfileField)))fail('Only biography and supported contact links can be edited.',422);for(const field of accountProfileFields)if(Object.hasOwn(object,field)){if(typeof object[field]!=='string')fail('Invalid '+field+' in native public profile.',422);const text=value((object[field] as string).replace(/^\p{White_Space}+|\p{White_Space}+$/gu,''),field,422);if(text!==state[field])patch[field]=text;}if(!Object.keys(patch).length)fail('There are no changed profile fields to save.',422);const before=state;busy=true;try{const response=await account.request('/user/'+userId,'PUT',{expectedAccountId:accountId,expectedUserId:userId,version:before.version,...patch});account.check();if(response.status!==200)fail(response.status===409?'The account or profile changed. Reload before trying again.':'The public profile change was not confirmed ('+response.status+').',response.status);const result=observation(response.body,true);if(result.version!==before.version!+1||result.username!==before.username||JSON.stringify(result.roles)!==JSON.stringify(before.roles)||accountProfileFields.some(field=>result[field]!== (patch[field]??before[field])))fail('Invalid confirmed native public profile receipt.');state=result;return view();}catch(error){state={...state,needsRecheck:true};throw error;}finally{busy=false;}}
 return{reload,save,view,check:account.check};
};}
export const loadAccountProfile=createAccountProfileClient();
